from pydantic import BaseModel, EmailStr, field_validator
from typing import Optional
from datetime import datetime
from enum import Enum


class EmergencyEnum(str, Enum):
    Yes = "Yes"
    No  = "No"


class StatusEnum(str, Enum):
    Active   = "Active"
    Inactive = "Inactive"


# ── Request: Create (no code — auto-generated by SP) ─────────
class BranchCreate(BaseModel):
    name:               str
    hospitalId:         int
    branchType:         str                 = "Main Hospital"
    address1:           str
    address2:           Optional[str]       = None
    country:            str
    state:              str
    city:               str
    postalCode:         str
    contactNumber:      str
    email:              Optional[EmailStr]  = None
    branchManager:      Optional[str]       = None
    workingHours:       str
    emergencyAvailable: EmergencyEnum       = EmergencyEnum.Yes
    numberOfFloors:     Optional[int]       = None
    numberOfBeds:       Optional[int]       = None
    status:             StatusEnum          = StatusEnum.Active
    remarks:            Optional[str]       = None

    @field_validator("name", "address1", "country", "state",
                     "city", "postalCode", "contactNumber", "workingHours")
    @classmethod
    def not_empty(cls, v: str) -> str:
        if not v or not v.strip():
            raise ValueError("This field is required and cannot be blank")
        return v.strip()


# ── Request: Update (code is immutable) ──────────────────────
class BranchUpdate(BaseModel):
    name:               str
    hospitalId:         int
    branchType:         str                 = "Main Hospital"
    address1:           str
    address2:           Optional[str]       = None
    country:            str
    state:              str
    city:               str
    postalCode:         str
    contactNumber:      str
    email:              Optional[EmailStr]  = None
    branchManager:      Optional[str]       = None
    workingHours:       str
    emergencyAvailable: EmergencyEnum       = EmergencyEnum.Yes
    numberOfFloors:     Optional[int]       = None
    numberOfBeds:       Optional[int]       = None
    status:             StatusEnum          = StatusEnum.Active
    remarks:            Optional[str]       = None


# ── Response ─────────────────────────────────────────────────
class BranchResponse(BaseModel):
    id:                 int
    code:               str
    name:               str
    hospitalId:         int
    hospital:           str           # HospitalName from JOIN
    branchType:         str
    address1:           str
    address2:           Optional[str]
    country:            str
    state:              str
    city:               str
    postalCode:         str
    contactNumber:      str
    email:              Optional[str]
    branchManager:      Optional[str]
    workingHours:       str
    emergencyAvailable: str
    numberOfFloors:     Optional[int]
    numberOfBeds:       Optional[int]
    status:             str
    remarks:            Optional[str]
    createdDate:        Optional[datetime]
    modifiedDate:       Optional[datetime]

    class Config:
        from_attributes = True
